(174, 324, 'Flor de fuego ', '2025-06-09 13:06:59', 123530, 'Flor de fuego 2', '<p>Requerimiento: Elaborar texto para voz sobre el taco</p><p><br></p><p>1. Duración: Mínimo 15 segundos, máximo 18 a 20 segundos.</p><p>2. Contenido a incluir:</p><p>   - Descripción breve del taco.</p><p>   - Ingredientes principales </p><p>   - Enfatizar la experiencia de sabor y tradición.</p><p>3. Tono: Entusiasta y atractivo.</p><p><br></p><p>Link: https://mega.nz/folder/12NWhAAL#mCndw8tVTwc9cPSjrpPCBg</p><p><br></p><p>Nota: Consultar el menú</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'created', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(175, 331, 'JOAQUIN', '2025-06-10 11:13:24', 123526, 'STIKERS GORIMICHES (JOAQUIN) ', '<p>🔹 <strong>Requerimiento para Carlos – Diseño por José López</strong></p><p>Hola Carlos, por favor solicitar a José López lo siguiente:</p><p>Fecha de entrega: 06-10 A mas tardar a las 5 pm (HORA VENEZUELA)</p><p>Se necesita crear un <strong>sticker redondo de 3 pulgadas de diámetro</strong> para la marca <strong>Gorimiches (Joaquín)</strong>.</p><p>✔️ Utilizar el <strong>logo final aprobado de Gorimiches</strong> (el que quedó al final para Joaquín).</p><p>✔️ Incluir la página web: <a href=\"http://gorimiches.com\" rel=\"noopener noreferrer\" target=\"_blank\">http://gorimiches.com</a> </p><p>✔️ El diseño debe ser <strong>redondo</strong>, pensado para colocarse en vasos.</p><p>✔️ Este sticker debe elaborarse para impresión en material <strong>transparente</strong>.</p><p>✔️ Por favor, evaluar cuál de las versiones finales del logo es la más adecuada para este tipo de sticker transparente, garantizando que los elementos del diseño se vean correctamente en este formato.</p><p>Quedamos atentos para su revisión y confirmación del arte final antes de enviar a producción.</p>', 'finished', 1749569603, 1749570153, NULL, NULL, 0, 550, NULL, NULL, NULL, NULL, NULL, NULL),
(176, 331, 'Joaquín ', '2025-06-10 11:29:57', 123529, 'Gorimiches ', '<p>Link: https://mega.nz/folder/87sSjKBS#ZJjpro7k3c0hrqNLrXfAwA</p><p><br></p><p>Fecha de entrega: 06-10 A más tardar a las 5 pm (HORA VENEZUELA)</p><p><br></p><p>Se necesita crear un adhesivo redondo de 3 pulgadas de diámetro para la marca Gorimiches (Joaquín) .</p><p><br></p><p>✔️ Utilizar el logo final aprobado de Gorimiches (el que quedó al final para Joaquín).</p><p><br></p><p>✔️ Incluir la página web: http://gorimiches.com</p><p><br></p><p>✔️ El diseño debe ser redondo , pensado para colocarse en vasos.</p><p><br></p><p>✔️ Este adhesivo debe elaborarse para impresión en material transparente .</p><p><br></p><p>✔️ Por favor, evalúe cuál de las versiones finales del logo es la más adecuada para este tipo de pegatina transparente, garantizando que los elementos del diseño se vean correctamente en este formato.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749573279, 1749578869, NULL, NULL, 0, 5590, NULL, NULL, NULL, NULL, NULL, NULL),
(177, 324, 'Flor de fuego ', '2025-06-10 14:28:51', 123530, 'flor de fuego copys', '<p>Actividad: Elaborar copies para creativos de Flor de Fuego.</p><p><br></p><p>Instrucciones:</p><p><br></p><p>Revisar los links de contenido en el documento.</p><p><br></p><p>Crear textos atractivos basados en ese contenido.</p><p><br></p><p>Reflejar la esencia de Flor de Fuego.</p>', 'created', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(178, 331, 'Detrás del menú ', '2025-06-11 10:02:47', 123530, 'Nuevo post (reprogramación) ', '<p><br></p><p>Requerimiento:</p><p><br></p><p>- Elaborar nuevo texto basado en la imagen proporcionada.</p><p>- Parafrasear la información contenida en la imagen.</p><p>- Tomar en cuenta las siguientes notas:</p><p><br></p><p>1. cambio en la fecha se corrió para el miércoles 18 a las 7pm</p><p>2. Quita eso del acceso por 45 días al software del origen</p><p>3. Coloca que el evento es gratuito</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'created', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(179, 331, 'Detrás del menú ', '2025-06-11 10:30:25', 123529, 'Nuevo post ', '<p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749658792, 1749658795, NULL, NULL, 0, 3, NULL, NULL, NULL, NULL, NULL, NULL),
(180, 331, 'Detrás del menú ', '2025-06-11 10:30:26', 123529, 'Nuevo post ', '<p>Requerimiento (urgente)</p><p><br></p><p>- Elaborar un diseño formato post de reprogramación de la fecha del evento.</p><p><br></p><p>- Asegurarse de que el diseño no se parezca al anterior.</p><p>- Revisar la distribución del texto y los elementos utilizados en el diseño.</p><p>- Incluir elementos relacionados con el contenido o material del evento.</p><p><br></p><p>Texto del post:</p><p><br></p><p>DETRÁS DEL MENU</p><p><br></p><p>IMPULSA LAS FINANZAS DE TU RESTAURANTE.</p><p><br></p><p>DESCUBRE CÓMO CALCULAR EL COSTO REAL DE TUS RECETAS, AJUSTAR TUS PRECIOS PARA GANAR MÁS Y DISEÑAR UN MENÚ ESTRATÉGICO CON APOYO DE HERRAMIENTAS DIGITALES.</p><p><br></p><p>¿QUÉ INCLUYE?</p><p><br></p><p>EJERCICIO REAL DE COSTEO (EJEMPLO: CUÁNTO CUESTA UN TACO)</p><p><br></p><p>GUÍA SEMANAL DE MARKETING + PLANTILLAS DE CONTENIDO</p><p><br></p><p>INTRODUCCIÓN PRÁCTICA A CANVA Y CAPCUT</p><p><br></p><p>PANEL DE EXPERTOS + SESIÓN INTERACTIVA</p><p><br></p><p>GRABACIÓN DEL EVENTO Y RECURSOS</p><p><br></p><p>MIÉRCOLES 6/18</p><p><br></p><p>EVENTO 100% EN LÍNEA Y COMPLETAMENTE GRATUITO.</p><p><br></p><p>REGÍSTRATE AHORA EN: WWW.DETRASDELMENU.COM</p><p><br></p><p>TAMBIÉN PUEDES MANDAR UN MENSAJE DIRECTO PARA COMPRAR TU ENTRADA:</p><p><br></p><p>(630) 747 5682</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749653140, 1749658766, NULL, NULL, 0, 5626, NULL, NULL, NULL, NULL, NULL, NULL),
(181, 331, 'La conchita ', '2025-06-11 16:31:24', 123529, 'La conchita 7', '<p><br></p><p>Nombre del producto:</p><p>Pan</p><p>Harina de Maíz</p><p>Pre-cooked Corn Meal</p><p>‌</p><p>Requerimiento: Elaborar (post animado)</p><p><br></p><p>Texto del diseño</p><p>.</p><p>.</p><p>.</p><p>PAN</p><p>HARINA DE MAÍZ / Pre-cooked Corn Meal</p><p>\"Para el desayuno o lo que se te antoje\".</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749674345, 1749677586, NULL, NULL, 0, 3241, NULL, NULL, NULL, NULL, NULL, NULL),
(182, 331, 'La conchita ', '2025-06-11 16:38:21', 123529, 'La conchita 8', '<p><br></p><p><br></p><p>Nombre del producto:</p><p><br></p><p>Barilla</p><p><br></p><p>Salsa para espagueti</p><p><br></p><p>Spaghetti Sauce</p><p><br></p><p> </p><p><br></p><p>Requerimiento: Elaborar diseño formato (post animado)</p><p><br></p><p>.</p><p>.</p><p>.</p><p><br></p><p>Texto del diseño</p><p><br></p><p>SALSA \"BARILLA\" PARA ESPAGUETI</p><p>Spaghetti Sauce</p><p><br></p><p>\"Tu pasta merece algo mejor\"</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749677596, 1749680174, NULL, NULL, 0, 2578, NULL, NULL, NULL, NULL, NULL, NULL),
(183, 264, 'La conchita ', '2025-06-11 16:40:53', 123529, 'La conchita 9', '<p><br></p><p>Nombre del producto:</p><p>Margarita</p><p>Queso Fresco</p><p>Crumbling Cheese</p><p>‌</p><p>Requerimiento: Elaborar diseño formato (post animado)</p><p>.</p><p>.</p><p>Texto del diseño:</p><p>QUESO FRESCO MARGARITA</p><p>Crumbling Cheese</p><p>\"El toque criollo que no puede faltar en tu plato\".</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749680188, 1749683087, NULL, NULL, 0, 2899, NULL, NULL, NULL, NULL, NULL, NULL),
(184, 324, 'Flor de fuego ', '2025-06-12 09:14:23', 123529, 'Tarjeta de descuento ', '<p>Requerimiento: Elaborar tarjetas de descuento para flor de fuego</p><p><br></p><p>Esto es para una targeta de presentación </p><p><br></p><p>Contenido de la tarjeta </p><p><br></p><p>🎉 Welcome, Neighbor!</p><p>Enjoy 10% OFF Brunch</p><p>🕚 From 11:00 AM to 2:00 PM</p><p>Only at Flor de Fuego</p><p><br></p><p>Back card  (con QR code  el mismo del banner) </p><p>Terms &amp; Conditions:</p><p>✅ Must present this card to redeem discount.</p><p>🚫 Cannot be combined with other offers, promotions, or rewards.</p><p>📍 One-time use per visit.</p><p><br></p><p> 1 779-426-7015</p><p><br></p><p>330 W NORTH ST, MANHATTAN, IL 60442</p><p><br></p><p><br></p><p><br></p><p>Importante: Recordar el sangrado para el recorte </p><p><br></p><p>Fecha límite: 1 pm</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1749738274, 1749746552, NULL, NULL, 0, 8278, NULL, NULL, NULL, NULL, NULL, NULL),
