(201, 336, 'Salvador ', '2025-06-21 21:18:55', 123532, 'ELABORACIÓN DE (2) HISTORIAS DE IG', '<p>🔔 <strong>Notificación Importante de Gestión de Tareas – Elaboración de (2 Historias) LPT ROOFTOP </strong></p><p>Hola Alison buenas noches,</p><p>Te comento que el nuevo requerimiento ha sido cargado en la ficha correspondiente de Trello. Aquí les dejamos el link para su revisión inmediata: </p><p><br></p><p><a href=\"https://trello.com/c/Oc1w3dQS/1476-historias-2-lpt-rooftop\" rel=\"noopener noreferrer\" target=\"_blank\">https://trello.com/c/Oc1w3dQS/1476-historias-2-lpt-rooftop</a></p><p><br></p><p><span style=\"background-color: rgb(247, 250, 252); color: rgb(82, 95, 127);\">Esto hay que entregarlo el Lunes 06-23 las 3 pm (hora Bolivia)</span></p><p><br></p><p>⚠️ <strong>Recordatorio clave del uso del sistema de gestión:</strong></p><p> 1️⃣ Solo deben marcar la tarea como \"Iniciada\" cuando efectivamente comiencen a trabajar en ella.</p><p> 2️⃣ Si detienen temporalmente la actividad, deben cambiar el estado a \"Pausada\".</p><p> 3️⃣ Al finalizar completamente la tarea, deben marcarla como \"Finalizada\" y notificar de inmediato al <strong>Project Manager de Operaciones</strong>, para que pueda proceder con sus gestiones y a su vez informar a la <strong>Project Manager de Comunicaciones</strong>.</p><p><br></p><p>Su correcta gestión asegura el buen flujo de trabajo de todo el equipo. ¡Gracias por su compromiso!</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'finished', 1750695333, 1750715947, '1750698471,1750704098,1750714546,1750715939', 'Descanso para la hora de almuerzo |||17:30 Salida de trabajo', 7020, 13594, NULL, NULL, NULL, NULL, NULL, NULL),
(202, 336, 'Salvador ', '2025-06-21 21:39:30', 123533, 'ELABORACIÓN DE (3) HISTORIAS DE IG', '<p>Notificación de Gestión de Tareas – ELABORACIÓN DE HISTORIAS DE INSTAGRAM </p><p><br></p><p>Hola Aaron, buenas noches! </p><p>por favor revisa este el link de TRELLO para realizar la gestión:</p><p><br></p><p>LINK: https://trello.com/c/1X8bjJ05/1473-historias-3-lpt-rooftop</p><p><br></p><p>Esto hay que entregarlo el Lunes 06-23 las 3 pm (hora Venezuela)</p><p><br></p><p>⚠️ Recordatorio clave del uso del sistema de gestión:</p><p><br></p><p>1️⃣ Solo deben marcar la tarea como \"Iniciada\" cuando efectivamente comiencen a trabajar en ella.</p><p><br></p><p>2️⃣ Si detienen temporalmente la actividad, deben cambiar el estado a \"Pausada\".</p><p><br></p><p>3️⃣ Al finalizar completamente la tarea, deben marcarla como \"Finalizada\" y notificar de inmediato al Project Manager de Operaciones, para que pueda proceder con sus gestiones y a su vez informar a la Project Manager de Comunicaciones.</p><p><br></p><p><br></p><p>¡Gracias por su compromiso!</p><p><br></p>', 'finished', 1750682187, 1750715769, '1750698309,1750703636', 'Razón: Hora de almuerzo y a la espera de aprobación de la 3era historia', 5327, 28255, NULL, NULL, NULL, NULL, NULL, NULL),
